## Code Style Examples

### Error Handling Pattern
```typescript
// CORRECT: use Result type
async function getUser(id: string): Promise<Result<User, AppError>> {
  try {
    const user = await db.users.findById(id);
    return ok(user);
  } catch (e) {
    return err(new AppError('USER_NOT_FOUND', e));
  }
}

// WRONG: throwing errors
async function getUser(id: string): Promise<User> {
  // Don't do this
  return await db.users.findById(id); // throws on failure
}
```

