#!/bin/bash
# PostToolUse hook for Write tool
FILE=$(echo "$CLAUDE_TOOL_INPUT" | jq -r '.file_path')
if [[ "$FILE" == *.ts || "$FILE" == *.tsx ]]; then
  TIMESTAMP=$(date +%Y-%m-%dT%H:%M:%S)
  echo "[$TIMESTAMP] Modified: $FILE" >> .claude/session-log.md
fi

